#!/usr/bin/env python3
"""يبني content/hadith.json («حديث الأسبوع»): لفظ كل حديث مقطوع آليًّا من نص صحيحي البخاري ومسلم (fawazahmed0/hadith-api، ara-bukhari.json وara-muslim.json) ولا يُكتب باليد.
الرقم الأول في كل سطر رقم الحديث في الملف (ترقيم مسلم فيه تسلسلي)، والثاني الرقم المشهور. المعنى والتحدي من تأليف Claude للطفل.
الاستعمال: python3 tools/hadith_build.py <مجلد ملفات ara-bukhari.json وara-muslim.json>"""
import json, re, sys
D={f:{str(h['hadithnumber']):h for h in json.load(open(f'{sys.argv[1]}/ara-{f}.json'))['hadiths']} for f in ['bukhari','muslim']}
MARK=re.compile(r'[ً-ْٰـ‏‎]')
def strip_map(t):
    out=[];idx=[]
    for i,c in enumerate(t):
        if MARK.match(c): continue
        out.append(c); idx.append(i)
    return ''.join(out),idx
def norm(s): return MARK.sub('',s)
def span(col,num,start,end):
    t=D[col][str(num)]['text']; s,idx=strip_map(t)
    a=s.find(norm(start)); 
    if a<0: return None
    b=s.find(norm(end),a)
    if b<0: return None
    b+=len(norm(end))
    j=idx[b-1]+1
    while j<len(t) and MARK.match(t[j]): j+=1
    return t[idx[a]:j]
def search(col,kw):
    k=[norm(x) for x in kw]
    return [n for n,h in D[col].items() if all(x in norm(h['text']) for x in k)][:5]
AR='٠١٢٣٤٥٦٧٨٩'; a=lambda n:''.join(AR[int(c)] for c in str(n))
# (المصدر، الرقم في الملف، الرقم المشهور، بداية اللفظ، نهايته، الراوي، معناه للطفل، تحدي الأسبوع)
