out=[]; bad=[]
for col,f,n,s,e,rawi,sh,ch in H:
    t=span(col,f,s,e)
    if not t: bad.append((col,f,s)); continue
    t=t.replace('‏.‏','').replace('‏"‏','').strip(' "\'‏')
    if col=='muslim' and n==55: t=f'{t}»، قُلْنَا: لِمَنْ؟ قَالَ: «'+span(col,f,'لله ولكتابه','وعامتهم')
    if n==2444: t=f'{t}»، قَالُوا: يَا رَسُولَ اللَّهِ، هَذَا نَنْصُرُهُ مَظْلُومًا، فَكَيْفَ نَنْصُرُهُ ظَالِمًا؟ قَالَ: «'+span(col,f,'تأخذ فوق يديه','فوق يديه')
    out.append({'text':t,'rawi':rawi,'source':('صحيح البخاري' if col=='bukhari' else 'صحيح مسلم')+'، رقم '+a(n),'sharh':sh,'challenge':ch})
assert not bad, bad
F = {'عائشة': 'رضي الله عنها', 'عبد الله بن عمر': 'رضي الله عنهما', 'عبد الله بن عمرو': 'رضي الله عنهما', 'جابر بن عبد الله': 'رضي الله عنهما', 'عمر بن أبي سلمة': 'رضي الله عنهما'}
for o in out: o['rida'] = F.get(o['rawi'], 'رضي الله عنه')
data = {'_note': 'مولَّد بـ tools/hadith_build.py؛ لا يُعدَّل باليد. text لفظ الحديث مقطوعًا حرفيًّا من الصحيحين (الشكل من المصدر)، وما بين »…« داخله حوار من الحديث نفسه. sharh معنى مبسَّط للطفل وchallenge تحدي الأسبوع، وكلاهما من تأليف Claude. الترتيب: أسبوع لكل حديث يبدأ يوم السبت، والدورة تبدأ من start.', 'start': '2026-11-21', 'list': out}
open('content/hadith.json', 'w', encoding='utf-8').write(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
print(len(out), 'حديثًا')
